text:
Componente para Next.js App Router, TypeScript y Tailwind v4. Bloquea el scroll —incluido iOS—, conserva la posición, cierra con `Escape` y mantiene el foco dentro del menú.

```tsx
"use client";

import { useEffect, useId, useRef, useState } from "react";

const navigation = [
  { label: "Inicio", href: "/" },
  { label: "Servicios", href: "/servicios" },
  { label: "Proyectos", href: "/proyectos" },
  { label: "Contacto", href: "/contacto" },
];

export function MobileMenu() {
  const [isOpen, setIsOpen] = useState(false);
  const menuId = useId();
  const menuRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    if (!isOpen) return;

    const body = document.body;
    const root = document.documentElement;
    const scrollY = window.scrollY;
    const scrollbarWidth = window.innerWidth - root.clientWidth;

    const previousStyles = {
      bodyOverflow: body.style.overflow,
      bodyPosition: body.style.position,
      bodyTop: body.style.top,
      bodyWidth: body.style.width,
      bodyPaddingRight: body.style.paddingRight,
      rootOverflow: root.style.overflow,
      rootScrollBehavior: root.style.scrollBehavior,
    };

    root.style.overflow = "hidden";
    body.style.overflow = "hidden";
    body.style.position = "fixed";
    body.style.top = `-${scrollY}px`;
    body.style.width = "100%";

    if (scrollbarWidth > 0) {
      body.style.paddingRight = `${scrollbarWidth}px`;
    }

    const focusableSelector = [
      "a[href]",
      "button:not([disabled])",
      "[tabindex]:not([tabindex='-1'])",
    ].join(",");

    const focusFirstElement = () => {
      const firstFocusable =
        menuRef.current?.querySelector<HTMLElement>(focusableSelector);

      firstFocusable?.focus();
    };

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setIsOpen(false);
        return;
      }

      if (event.key !== "Tab") return;

      const focusableElements = Array.from(
        menuRef.current?.querySelectorAll<HTMLElement>(focusableSelector) ?? [],
      );

      if (focusableElements.length === 0) return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements.at(-1);

      if (event.shiftKey && document.activeElement === firstElement) {
        event.preventDefault();
        lastElement?.focus();
      } else if (!event.shiftKey && document.activeElement === lastElement) {
        event.preventDefault();
        firstElement.focus();
      }
    };

    document.addEventListener("keydown", handleKeyDown);
    requestAnimationFrame(focusFirstElement);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);

      root.style.overflow = previousStyles.rootOverflow;
      body.style.overflow = previousStyles.bodyOverflow;
      body.style.position = previousStyles.bodyPosition;
      body.style.top = previousStyles.bodyTop;
      body.style.width = previousStyles.bodyWidth;
      body.style.paddingRight = previousStyles.bodyPaddingRight;

      root.style.scrollBehavior = "auto";
      window.scrollTo({ top: scrollY, left: 0, behavior: "auto" });
      root.style.scrollBehavior = previousStyles.rootScrollBehavior;

      triggerRef.current?.focus();
    };
  }, [isOpen]);

  return (
    <>
      <button
        ref={triggerRef}
        type="button"
        aria-controls={menuId}
        aria-expanded={isOpen}
        aria-label="Abrir menú"
        onClick={() => setIsOpen(true)}
        className="grid size-12 place-items-center rounded-full border border-black/15 bg-white text-black transition-colors hover:bg-black hover:text-white md:hidden"
      >
        <span className="sr-only">Abrir menú</span>
        <span aria-hidden="true" className="grid gap-1.5">
          <span className="block h-px w-5 bg-current" />
          <span className="block h-px w-5 bg-current" />
        </span>
      </button>

      {isOpen ? (
        <div
          ref={menuRef}
          id={menuId}
          role="dialog"
          aria-modal="true"
          aria-label="Menú principal"
          className="fixed inset-0 z-50 flex min-h-dvh flex-col bg-[#f3f0e8] text-[#161616] md:hidden"
        >
          <header className="flex items-center justify-between border-b border-black/15 px-6 py-5">
            <span className="text-xs font-semibold uppercase tracking-[0.22em]">
              Navegación
            </span>

            <button
              type="button"
              aria-label="Cerrar menú"
              onClick={() => setIsOpen(false)}
              className="grid size-12 place-items-center rounded-full border border-black/15 transition-colors hover:bg-black hover:text-white"
            >
              <span aria-hidden="true" className="relative block size-5">
                <span className="absolute left-0 top-1/2 block h-px w-5 rotate-45 bg-current" />
                <span className="absolute left-0 top-1/2 block h-px w-5 -rotate-45 bg-current" />
              </span>
            </button>
          </header>

          <nav className="flex flex-1 items-center px-6 py-10">
            <ul className="w-full">
              {navigation.map((item, index) => (
                <li key={item.href} className="border-b border-black/15">
                  <a
                    href={item.href}
                    onClick={() => setIsOpen(false)}
                    className="group flex items-baseline justify-between py-5"
                  >
                    <span className="text-4xl font-medium tracking-[-0.05em] transition-transform group-hover:translate-x-2">
                      {item.label}
                    </span>

                    <span className="text-xs tabular-nums text-black/45">
                      {String(index + 1).padStart(2, "0")}
                    </span>
                  </a>
                </li>
              ))}
            </ul>
          </nav>

          <footer className="flex justify-between px-6 py-6 text-xs uppercase tracking-[0.18em] text-black/50">
            <span>Menú</span>
            <span>{new Date().getFullYear()}</span>
          </footer>
        </div>
      ) : null}
    </>
  );
}
```

Se oculta desde `md` en adelante; cambia `md:hidden` si tu breakpoint móvil es distinto.
